export const newStyles={full:'Full Pallet · Shelf',stack:'Stacking Trays · Pallet',flange:'Flange Tray',end36:'36-inch Endcap',end48:'48-inch Endcap'};
export const isEndcap=t=>t==='end36'||t==='end48';
export const isNewStyle=t=>Object.hasOwn(newStyles,t);
export function phase3Preset(type,defaults){const common={...defaults,type,color:'#e7e4dc',dividers:false,compartments:2,dividerPositions:[],sign:false,risers:0,tierHeights:[],tierDepths:[],shelfDepths:[],slots:{},removalClearance:.5,guideWarnings:true,guideBodyMax:43,guideTrayMax:14,guideEndcapMax:70};
 if(type==='full')return {...common,width:48,depth:40,height:56,base:5,header:8,levels:4,faces:2,palletWidth:48,palletDepth:40};
 if(type==='stack')return {...common,width:48,depth:40,height:48,base:5,header:0,levels:4,palletWidth:48,palletDepth:40,trayWidth:23.7,trayDepth:19.7,trayColumns:2,trayRows:2,moduleGap:.3,trayOrientation:0,trayFacing:'outward'};
 if(type==='flange')return {...common,width:29.5,depth:14,height:12,base:0,header:0,levels:1,lip:2,flangeHeight:6,flangeExtent:1,rearHeight:8,retention:true};
 return {...common,width:type==='end36'?35.5:47.5,depth:15,height:70,base:5,header:0,levels:5,lip:.6,fixtureWidth:type==='end36'?36:48,fixtureDepth:18,fixtureHeight:77.75,endcapMode:'fixture'};
}
export function splitWidth(width,board,count=1,positions=[]){if(!Number.isInteger(count)||count<1||count>6||!Number.isFinite(width)||width<=board*(count-1))throw Error('Use 1–6 compartments with enough clear width.');let cuts;if(!positions?.length)cuts=Array.from({length:count-1},(_,i)=>(i+1)/count);else{if(positions.length!==count-1||positions.some((p,i)=>!Number.isFinite(p)||p<=0||p>=100||(i&&p<=positions[i-1])))throw Error(`Enter ${count-1} increasing divider positions between 0 and 100%.`);cuts=positions.map(x=>x/100);}const values=[0,...cuts,1],clear=width-board*(count-1),out=[];let left=-width/2;for(let i=0;i<count;i++){const w=clear*(values[i+1]-values[i]);out.push({w,x:left+w/2});left+=w+board;}return out;}
function compartments(s,zone){const parts=splitWidth(zone.w,s.board,s.dividers?(s.compartments??2):1,s.dividers?s.dividerPositions:[]);const angle=zone.angle||0,c=Math.cos(angle),n=Math.sin(angle);return parts.map((p,i)=>({...zone,id:`${zone.key}:${i}`,comp:i,w:p.w,x:zone.x+p.x*c,z:zone.z-p.x*n,angle,worldW:Math.abs(c)*p.w+Math.abs(n)*zone.d,worldD:Math.abs(n)*p.w+Math.abs(c)*zone.d}));}
function shelfLevels(s,deck){const body=s.height-s.base-s.header,out=[];let rise=0;for(let tier=0;tier<s.levels;tier++){const pitch=s.tierHeights?.[tier]??body/s.levels;if(!Number.isFinite(pitch)||pitch<=deck+.6)throw Error(`Shelf ${tier+1}: pitch must exceed the deck and support allowance.`);out.push({tier,pitch,y:s.base+rise+deck,clear:pitch-deck-(tier<s.levels-1?.6:0),deck});rise+=pitch;}if(Math.abs(rise-body)>.01)throw Error(`Shelf pitches must sum to ${body.toFixed(2)} in; currently ${rise.toFixed(2)}.`);return out;}
function guard(s){const fields=['width','depth','height','base','header','board','lip','gap','levels'];if(fields.some(k=>!Number.isFinite(s[k]))||['width','depth','height','board'].some(k=>s[k]<=0)||['base','header','lip','gap'].some(k=>s[k]<0)||!Number.isInteger(s.levels)||s.levels<1||s.levels>12||s.width>120||s.depth>80||s.height>120)throw Error('Enter valid dimensions: W/H ≤120 in, D ≤80 in, and 1–12 whole levels.');if(s.height-s.base-s.header<=s.board||s.lip>=s.height-s.base-s.header)throw Error('Base, header, board or lip leaves no merchandise opening.');if((s.removalClearance??0)<0||!Number.isFinite(s.removalClearance??0))throw Error('Removal clearance must be nonnegative.');}
export function phase3Surfaces(s){try{guard(s);const B=s.board,body=s.height-s.base-s.header,result=[],zones=[],modules=[],deck=Math.max(.25,B*2);let levels=[],iw=s.width-2*B,id=s.depth-2*B;
 if(s.type==='full'){
  if(![2,4].includes(s.faces))throw Error('Choose two or four shoppable pallet faces.');if(!Number.isFinite(s.palletWidth)||!Number.isFinite(s.palletDepth)||s.width>s.palletWidth||s.depth>s.palletDepth)throw Error('Display body overhangs its pallet. Increase the actual pallet or reduce the body.');const inset=Math.max(.6,B);iw=s.width-2*inset;id=s.depth-2*inset;if(iw<=B||id<=B)throw Error('Reinforced corners leave no usable pallet interior.');levels=shelfLevels(s,deck);
  for(const level of levels){const zoneList=s.faces===2?[{face:'front',w:iw,d:(id-B)/2,x:0,z:(id+B)/4,angle:0},{face:'back',w:iw,d:(id-B)/2,x:0,z:-(id+B)/4,angle:Math.PI}]:[{face:'front',w:iw,d:id/4-B/2,x:0,z:3*id/8+B/4,angle:0},{face:'back',w:iw,d:id/4-B/2,x:0,z:-(3*id/8+B/4),angle:Math.PI},{face:'right',w:id/2-B,d:(iw-B)/2,x:(iw+B)/4,z:0,angle:Math.PI/2},{face:'left',w:id/2-B,d:(iw-B)/2,x:-(iw+B)/4,z:0,angle:-Math.PI/2}];
   for(const q of zoneList){const configured=s.shelfDepths?.[level.tier];if(configured!==undefined){if(!Number.isFinite(configured)||configured<=B||configured>q.d)throw Error(`Shelf ${level.tier+1}: merchandise depth exceeds the ${q.face} zone (${q.d.toFixed(2)} in).`);const shift=(q.d-configured)/2;q.x+=Math.sin(q.angle)*shift;q.z+=Math.cos(q.angle)*shift;q.d=configured;}const z={...level,...q,key:`${q.face}:${level.tier}`,lip:s.lip};zones.push(z);result.push(...compartments(s,z));}
  }
 }else if(s.type==='stack'){
  for(const k of ['trayWidth','trayDepth','moduleGap','palletWidth','palletDepth'])if(!Number.isFinite(s[k])||s[k]<(k==='moduleGap'?0:.1))throw Error('Enter positive tray/pallet dimensions and a nonnegative module gap.');for(const k of ['trayColumns','trayRows'])if(!Number.isInteger(s[k])||s[k]<1||s[k]>6)throw Error('Use 1–6 tray rows/columns.');if(![0,90].includes(s.trayOrientation))throw Error('Tray orientation must be 0° or 90°.');if(s.header!==0)throw Error('Stacked-tray shipping configuration uses no fixed header.');if(s.width>s.palletWidth||s.depth>s.palletDepth)throw Error('Stacked display area overhangs its pallet.');
  const rotated=s.trayOrientation===90,ow=rotated?s.trayDepth:s.trayWidth,od=rotated?s.trayWidth:s.trayDepth,gridW=s.trayColumns*ow+(s.trayColumns-1)*s.moduleGap,gridD=s.trayRows*od+(s.trayRows-1)*s.moduleGap;
  if(gridW>s.width+.001||gridD>s.depth+.001)throw Error(`Tray grid ${gridW.toFixed(2)} × ${gridD.toFixed(2)} in exceeds the ${s.width} × ${s.depth} in display area (${s.trayOrientation}° tray orientation).`);const corner=Math.max(.5,B);if(s.trayWidth<=2*corner||s.trayDepth<=2*corner)throw Error('Tray dimensions leave no space inside compression posts.');levels=shelfLevels(s,B);
  for(const l of levels)for(let row=0;row<s.trayRows;row++)for(let col=0;col<s.trayColumns;col++){const module=row*s.trayColumns+col,x=-gridW/2+ow/2+col*(ow+s.moduleGap),z=gridD/2-od/2-row*(od+s.moduleGap),angle=(rotated?Math.PI/2:0)+(s.trayFacing==='outward'&&row>=s.trayRows/2?Math.PI:0),m={...l,module,row,col,x,z,w:s.trayWidth,d:s.trayDepth,angle,bottom:l.y-B,post:corner};modules.push(m);const q={...l,key:`${l.tier}:${module}`,module,face:`Tray ${module+1}`,w:s.trayWidth-2*corner,d:s.trayDepth-2*corner,x,z,angle,lip:s.lip};zones.push(q);result.push(...compartments(s,q));}
  if(result.some(x=>x.clear<=s.lip))throw Error('Tray lip leaves no clear module opening.');return {issues:[],surfaces:result,zones,modules,levels,body,iw,id,deck:B,gridW,gridD,stepped:false};
 }else if(s.type==='flange'){
  if(s.levels!==1||s.base!==0||s.header!==0)throw Error('A flange tray uses one level with no pallet/header.');for(const k of ['flangeHeight','flangeExtent','rearHeight'])if(!Number.isFinite(s[k])||s[k]<=0)throw Error('Enter positive flange and rear-support dimensions.');if(s.flangeHeight>s.height-B||s.rearHeight>s.height-B||s.flangeHeight<s.lip)throw Error('Flange/rear support must fit the total height; side flange must reach the front lip.');const bodyW=s.width-2*s.flangeExtent,inset=Math.max(B,s.retention?.3:B);iw=bodyW-2*inset;id=s.depth-2*B;if(iw<=0||id<=0)throw Error('Flanges/retention tabs leave no internal merchandise space.');const q={key:'0',tier:0,face:'Tray',w:iw,d:id,x:0,z:0,y:B,clear:s.height-B,lip:s.lip,deck:B,angle:0};zones.push(q);result.push(...compartments(s,q));levels=[q];
 }else if(isEndcap(s.type)){
  const nominal=s.type==='end36'?36:48;if(s.fixtureWidth!==nominal)throw Error(`This endcap uses a ${nominal}-inch fixture width.`);for(const k of ['fixtureDepth','fixtureHeight'])if(!Number.isFinite(s[k])||s[k]<=0)throw Error('Enter valid fixture depth/height.');if(!['fixture','corrugated'].includes(s.endcapMode))throw Error('Choose metal fixture or attached corrugated insert.');if(s.width>s.fixtureWidth-.25||s.depth>s.fixtureDepth||s.height>s.fixtureHeight)throw Error('Display/selling area extends beyond the physical fixture.');if(s.base<2)throw Error('Fixture base/kickplate needs at least 2 inches.');
  const inset=s.endcapMode==='corrugated'?Math.max(.4,B):B,plate=s.endcapMode==='fixture'?.2:deck;iw=s.width-2*inset;levels=shelfLevels(s,plate);
  for(const l of levels){const depth=s.shelfDepths?.[l.tier]??s.depth;if(!Number.isFinite(depth)||depth<=2*B||depth>s.depth)throw Error(`Shelf ${l.tier+1}: depth must be inside the ${s.depth}-inch selling area.`);const q={...l,key:`${l.tier}`,face:'Front',w:iw,d:depth-2*B,x:0,z:(s.fixtureDepth-depth)/2,y:l.y,angle:0,lip:s.lip,outerDepth:depth};zones.push(q);result.push(...compartments(s,q));}
 }
 if(result.some(x=>x.w<=0||x.d<=0||x.clear<=s.lip))throw Error('A wall, support or front lip leaves no clear merchandise volume.');return {issues:[],surfaces:result,zones,modules,levels,body,iw,id,deck,stepped:false};
 }catch(e){return {issues:[e.message],surfaces:[],zones:[],modules:[],levels:[]};}}
export function phase3Notes(s){const n=[],body=s.height-s.base-s.header,max=s.guideBodyMax??43;if(s.type==='full'||s.type==='stack'){if(s.palletWidth!==48||![20,40].includes(s.palletDepth))n.push('Pallet: reference footprints are 48 × 40 or 48 × 20 in.');if(body>max)n.push(`Body height ${body.toFixed(2)} in exceeds the configured ${max}-inch reference.`);if(s.header>8)n.push('Header exceeds the 8-inch reference.');const underW=(s.palletWidth-s.width)/2,underD=(s.palletDepth-s.depth)/2;if(underW>1||underD>1)n.push(`Display underhang W/D is ${underW.toFixed(2)} / ${underD.toFixed(2)} in per edge (reference ≤1).`);if(underW<0||underD<0)n.push('Body overhangs the pallet footprint.');if(s.type==='stack'){const ow=s.trayOrientation===90?s.trayDepth:s.trayWidth,od=s.trayOrientation===90?s.trayWidth:s.trayDepth,gw=ow*s.trayColumns+(s.trayColumns-1)*s.moduleGap,gd=od*s.trayRows+(s.trayRows-1)*s.moduleGap;if((s.palletWidth-gw)/2>1||(s.palletDepth-gd)/2>1)n.push('Stacked tray grid leaves more than 1 inch of pallet underhang per edge.');}}
 if(s.type==='flange'){if(s.depth>(s.guideTrayMax??14))n.push('Tray depth exceeds the configured 14-inch reference.');if(s.lip<2)n.push('Front lip is below the 2-inch guide default.');if(![29.5,35.5,47.5].includes(s.width))n.push('Confirm flange-inclusive width against the shelf-width class.');}
 if(isEndcap(s.type)){if(s.endcapMode==='corrugated'&&s.height>(s.guideEndcapMax??70))n.push('Corrugated insert height exceeds the configured 70-inch reference.');if(s.endcapMode==='corrugated'&&s.depth>15)n.push('Corrugated insert depth exceeds 15 inches.');if(s.width>(s.type==='end36'?35.5:47.5))n.push('Insert width exceeds the nominal shelf class reference.');n.push('Endcap attachment, loads and shopper access need physical verification.');}return n;}
